import * as Stomp from 'stompjs';
import * as SockJS from 'sockjs-client';
export class WebSocketAPI {
  constructor(notifiComponent) {
    this.webSocketEndPoint = 'http://localhost:8091/websocket';
    this.topic = "/topic/user";
    this.notifiComponent = notifiComponent;
  }
  _connect() {
    console.log("Initialize WebSocket Connection");
    let websocket = new SockJS(this.webSocketEndPoint);
    this.stompClient = Stomp.over(websocket);
    const _this = this;
    _this.stompClient.connect({}, function (frame) {
      _this.stompClient.subscribe(_this.topic, function (sdkEvent) {
        _this.onMessageReceived(sdkEvent);
      });
      //_this.stompClient.reconnect_delay = 2000;
    }, this.errorCallBack);
  }
  _disconnect() {
    if (this.stompClient !== null) {
      this.stompClient.disconnect();
    }
    console.log("Disconnected");
  }
  // on error, schedule a reconnection attempt
  errorCallBack(error) {
    console.log("errorCallBack -> " + error);
    setTimeout(() => {
      this._connect();
    }, 5000);
  }
  /**
   * Send message to sever via web socket
   * @param {*} message
   */
  _send(message) {
    console.log("calling logout api via web socket");
    this.stompClient.send("/app/user", {}, JSON.stringify(message));
  }
  onMessageReceived(message) {
    console.log("Message Recieved from Server :: " + message);
    this.notifiComponent.handleMessage(JSON.stringify(message.body));
  }
}
